/* ============================================
   LIST
   Every marker sits in one gutter at the list's
   inline start: the native disc and number, the
   form controls' check, a named icon drawn by
   the icon font in ::before, or an item's own
   icon. The marker box is one line of the item's
   text tall, so it centres on the first line
   however the label wraps.
   ============================================ */

/* Base */
.ds-list {
  --ds-list-gutter: calc(var(--icon-size-500) + var(--gap-200));
  display: flex;
  flex-direction: column;
  gap: var(--ds-list-gap);
  margin: 0;
  padding: 0;
  padding-inline-start: var(--ds-list-gutter);
  color: var(--color-text-primary);
  list-style: none;
}

.ds-list__item {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  min-inline-size: 0;
}

.ds-list__label {
  overflow-wrap: break-word;
}

.ds-list__description {
  color: var(--color-text-secondary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* Sizes */
.ds-list--default {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
}

.ds-list--compact {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-list--compact .ds-list__description {
  font-size: var(--font-caption-size);
  line-height: var(--font-caption-line-height);
}

/* Spacing */
.ds-list--spacing-compact {
  --ds-list-gap: var(--gap-050);
}

.ds-list--spacing-default {
  --ds-list-gap: var(--gap-200);
}

.ds-list--spacing-relaxed {
  --ds-list-gap: var(--gap-400);
}

/* Markers: the gutter box every drawn marker sits in */
.ds-list__marker,
.ds-list--marker-icon .ds-list__item::before {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: calc(-1 * var(--ds-list-gutter));
  display: flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--icon-size-500);
  block-size: 1lh;
  --icon-size: var(--icon-size-500);
  color: var(--color-text-secondary);
}

/* Native markers: disc and number */
.ds-list--marker-disc {
  list-style: disc;
}

.ds-list--marker-number {
  list-style: decimal;
}

.ds-list--marker-disc .ds-list__item,
.ds-list--marker-number .ds-list__item {
  display: list-item;
}

.ds-list--marker-disc .ds-list__item > * + *,
.ds-list--marker-number .ds-list__item > * + * {
  margin-block-start: var(--gap-050);
}

.ds-list--marker-disc .ds-list__description,
.ds-list--marker-number .ds-list__description {
  display: block;
}

.ds-list__item::marker {
  color: var(--color-text-secondary);
  font-variant-numeric: tabular-nums;
}

/* The tick: the form controls' CheckIcon, drawn only in a check list */
.ds-list__tick {
  display: none;
}

.ds-list--marker-check .ds-list__tick {
  display: flex;
  color: var(--color-status-positive-text);
}

.ds-list__tick-glyph {
  inline-size: var(--icon-size-500);
  block-size: var(--icon-size-500);
  padding: var(--padding-050);
  box-sizing: border-box;
}

/* A named icon, drawn by the icon font from the list's custom property */
.ds-list--marker-icon .ds-list__item::before {
  content: var(--ds-list-marker);
  font-family: 'Material Symbols Rounded';
  font-size: var(--icon-size);
  line-height: 1;
  font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;
}

/* An item's own icon replaces the list's marker */
.ds-list__item--icon {
  display: flex;
  list-style: none;
}

.ds-list .ds-list__item--icon::before {
  content: none;
}

/* No marker, no gutter */
.ds-list--marker-none {
  padding-inline-start: 0;
}

.ds-list--marker-none .ds-list__item--icon {
  padding-inline-start: var(--ds-list-gutter);
}

.ds-list--marker-none .ds-list__item--icon .ds-list__marker {
  inset-inline-start: 0;
}

import React from 'react';
import { CheckIcon } from '../Checkbox/Checkbox';
import { mirrorClass } from '../../behaviors/direction';
import '../../fonts/material-symbols.css';
import './List.css';

/** Props owned by List itself; everything else falls through to the list element. */
type ListOwnProps = {
  /** `unordered` is a `ul`, `ordered` an `ol` whose order means something (steps), `plain` a `ul` with no markers and no indent. */
  variant?: 'unordered' | 'ordered' | 'plain';
  /** The mark before each item: a disc, the item's number, the form controls' check, nothing, or a Material Symbol name (`star`, `bolt`). Defaults to the variant's own: disc, number, none. */
  marker?: 'disc' | 'number' | 'check' | 'none' | (string & {});
  /** The room between items: `compact` for dense lists, `relaxed` for items with descriptions. */
  spacing?: 'compact' | 'default' | 'relaxed';
  /** The items' type size: `default` the paragraph face, `compact` the small paragraph face. */
  size?: 'default' | 'compact';
  /** The number an ordered list counts from. */
  start?: number;
  /** Count an ordered list down instead of up. */
  reversed?: boolean;
  /** The items, each a `ListItem`. */
  children?: React.ReactNode;
  /** Additional CSS classes. */
  className?: string;
};

export interface ListProps
  extends ListOwnProps,
    Omit<React.ComponentPropsWithRef<'ul'>, keyof ListOwnProps> {}

const NATIVE_MARKERS = new Set(['disc', 'number', 'check', 'none']);

/**
 * A list of items, ordered or not, marked with a disc, a number, a check or
 * an icon, each item optionally carrying a description under it: features,
 * steps, requirements. Server-renderable.
 */
export function List({
  variant = 'unordered',
  marker,
  spacing = 'default',
  size = 'default',
  start,
  reversed,
  className = '',
  style,
  children,
  ref,
  ...rest
}: ListProps) {
  const resolvedMarker = marker ?? (variant === 'ordered' ? 'number' : variant === 'plain' ? 'none' : 'disc');
  const iconMarker = !NATIVE_MARKERS.has(resolvedMarker);
  const classes = [
    'ds-list',
    `ds-list--${variant}`,
    `ds-list--marker-${iconMarker ? 'icon' : resolvedMarker}`,
    `ds-list--spacing-${spacing}`,
    `ds-list--${size}`,
    className,
  ]
    .filter(Boolean)
    .join(' ');
  const resolvedStyle = iconMarker
    ? ({ ...style, '--ds-list-marker': JSON.stringify(resolvedMarker) } as React.CSSProperties)
    : style;

  if (variant === 'ordered') {
    return (
      <ol
        {...(rest as React.ComponentPropsWithoutRef<'ol'>)}
        ref={ref as React.Ref<HTMLOListElement>}
        start={start}
        reversed={reversed}
        className={classes}
        style={resolvedStyle}
      >
        {children}
      </ol>
    );
  }
  return (
    <ul {...rest} ref={ref} className={classes} style={resolvedStyle}>
      {children}
    </ul>
  );
}

/** Props owned by ListItem itself; everything else falls through to the `li`. */
type ListItemOwnProps = {
  /** The item's text. */
  children?: React.ReactNode;
  /** A line of quieter text under the item. */
  description?: React.ReactNode;
  /** A Material Symbol name or a node that replaces this item's marker. A directional glyph mirrors in a right-to-left context. */
  icon?: string | React.ReactNode;
  /** Additional CSS classes. */
  className?: string;
};

export interface ListItemProps
  extends ListItemOwnProps,
    Omit<React.ComponentPropsWithRef<'li'>, keyof ListItemOwnProps> {}

/** One item of a List, with an optional description and an icon of its own. Server-renderable. */
export function ListItem({ children, description, icon, className = '', ref, ...rest }: ListItemProps) {
  const hasIcon = icon != null && icon !== false;
  const classes = ['ds-list__item', hasIcon && 'ds-list__item--icon', className].filter(Boolean).join(' ');
  return (
    <li {...rest} ref={ref} className={classes}>
      {hasIcon ? (
        typeof icon === 'string' ? (
          <span className={`ds-list__marker material-symbols-rounded ${mirrorClass(icon)}`} aria-hidden="true">
            {icon}
          </span>
        ) : (
          <span className="ds-list__marker" aria-hidden="true">
            {icon}
          </span>
        )
      ) : (
        <span className="ds-list__marker ds-list__tick" aria-hidden="true">
          <CheckIcon className="ds-list__tick-glyph" />
        </span>
      )}
      <span className="ds-list__label">{children}</span>
      {description != null && description !== false && <span className="ds-list__description">{description}</span>}
    </li>
  );
}
